/* 脉墙 PulseWall — compact dark monitor wall
   设计原则：位置恒定、就地更新、信号优先于装饰（Signal over Chrome） */

:root {
  --bg: #0d1017;
  --panel: #131826;
  --panel-2: #171d2e;
  --tile: #161c2b;
  --line: #232b40;
  --text: #e8ecf4;
  --muted: #8e9ab3;
  --faint: #5c6880;
  --accent: #4f8cff;

  --crit: #ff4d5e;
  --crit-bg: rgba(255, 77, 94, .09);
  --warn: #ffb020;
  --warn-bg: rgba(255, 176, 32, .09);
  --ok: #3fb96f;
  --ok-bg: rgba(63, 185, 111, .05);

  --mono: ui-monospace, "Cascadia Mono", Consolas, "JetBrains Mono", monospace;
}

* { box-sizing: border-box; }
html, body { height: 100%; }

body {
  margin: 0;
  display: flex;
  flex-direction: column;
  background: var(--bg);
  color: var(--text);
  font: 13px/1.45 "Segoe UI", system-ui, "Microsoft YaHei", sans-serif;
  overflow: hidden;
}

kbd {
  font: 11px var(--mono);
  color: var(--muted);
  border: 1px solid var(--line);
  border-radius: 3px;
  padding: 0 4px;
}

/* ---------- 顶部状态条 ---------- */
#status-bar {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 8px 14px;
  background: var(--panel);
  border-bottom: 1px solid var(--line);
  flex: 0 0 auto;
  white-space: nowrap;
}

.brand { display: flex; align-items: center; gap: 9px; margin-right: 4px; }
.logo {
  width: 22px; height: 22px; border-radius: 6px;
  background: linear-gradient(135deg, var(--accent), #7a5cff);
  box-shadow: 0 0 0 1px rgba(255,255,255,.08) inset;
}
.brand-text h1 { font-size: 14px; margin: 0; letter-spacing: .3px; }
.brand-text .en { color: var(--muted); font-weight: 400; font-size: 12px; }
.brand-text .sub { color: var(--faint); font-size: 11px; }

.heartbeat { display: flex; align-items: center; gap: 7px; min-width: 168px; }
.hb-dot {
  width: 8px; height: 8px; border-radius: 50%;
  background: var(--ok);
  animation: hb-pulse 1.2s ease-in-out infinite;
}
@keyframes hb-pulse { 0%,100% { opacity: 1; } 50% { opacity: .25; } }
.hb-label { font: 700 11px var(--mono); color: var(--ok); letter-spacing: 1px; }
#clock { font: 12px var(--mono); color: var(--muted); font-variant-numeric: tabular-nums; }
#hb.paused .hb-dot { background: var(--warn); animation-play-state: paused; }
#hb.paused .hb-label { color: var(--warn); }

.filters { display: flex; gap: 4px; }
.filters button {
  background: transparent;
  color: var(--muted);
  border: 1px solid var(--line);
  border-radius: 5px;
  padding: 3px 9px;
  font: inherit;
  cursor: pointer;
}
.filters button:hover { color: var(--text); border-color: var(--faint); }
.filters button.on { color: var(--text); background: var(--panel-2); border-color: var(--faint); }
.filters button b { font: 600 11px var(--mono); margin-left: 3px; font-variant-numeric: tabular-nums; }
.f-crit.on { color: var(--crit); border-color: var(--crit); }
.f-warn.on { color: var(--warn); border-color: var(--warn); }

.pause {
  margin-left: auto;
  display: flex; align-items: center; gap: 6px;
  background: var(--panel-2);
  color: var(--text);
  border: 1px solid var(--line);
  border-radius: 5px;
  padding: 4px 10px;
  font: inherit;
  cursor: pointer;
}
.pause:hover { border-color: var(--faint); }
.pause[aria-pressed="true"] { color: var(--warn); border-color: var(--warn); }
.pause-glyph { font-size: 9px; letter-spacing: -1px; }

button:focus-visible, .tile:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 1px;
}

/* ---------- 主布局 ---------- */
#layout {
  flex: 1 1 auto;
  display: grid;
  grid-template-columns: minmax(0, 1fr) 396px;
  min-height: 0;
}

/* ---------- 指标墙 ---------- */
#wall { overflow-y: auto; padding: 12px 14px 28px; min-height: 0; }

.group { margin-bottom: 14px; }
.group.dim { opacity: .3; }
.group-head {
  display: flex; align-items: baseline; gap: 8px;
  padding: 2px 2px 6px;
  border-bottom: 1px solid var(--line);
  margin-bottom: 8px;
}
.group-head h2 { font-size: 12.5px; margin: 0; color: var(--muted); letter-spacing: .5px; }
.g-count { font: 11px var(--mono); color: var(--faint); font-variant-numeric: tabular-nums; }
.g-count b { font-weight: 600; }
.g-count .n-crit { color: var(--crit); }
.g-count .n-warn { color: var(--warn); }

.tiles {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(212px, 1fr));
  gap: 8px;
}

.tile {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 3px;
  text-align: left;
  background: var(--tile);
  border: 1px solid var(--line);
  border-left: 3px solid var(--faint);
  border-radius: 6px;
  padding: 7px 9px 6px 10px;
  color: var(--text);
  font: inherit;
  cursor: pointer;
  transition: background-color .15s ease;
}
.tile:hover { border-color: var(--faint); border-left-color: inherit; }
.tile.dim { opacity: .14; pointer-events: none; }
.tile.sel { outline: 2px solid var(--accent); outline-offset: 1px; }

.tile.st-ok   { border-left-color: #3a465e; }
.tile.st-warn { border-left-color: var(--warn); background: linear-gradient(90deg, var(--warn-bg), var(--tile) 55%); }
.tile.st-crit { border-left-color: var(--crit); background: linear-gradient(90deg, var(--crit-bg), var(--tile) 55%); }

.t-top { display: flex; align-items: center; justify-content: space-between; gap: 6px; }
.t-name { color: var(--muted); font-size: 12px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.t-badge {
  flex: 0 0 auto;
  font: 700 10px var(--mono);
  letter-spacing: .5px;
  border-radius: 3px;
  padding: 1px 5px;
}
.st-ok .t-badge { color: var(--faint); background: rgba(255,255,255,.05); }
.st-warn .t-badge { color: #1a1200; background: var(--warn); }
.st-crit .t-badge { color: #fff; background: var(--crit); }

.t-mid { display: flex; align-items: baseline; gap: 5px; }
.t-val { font: 600 19px/1.1 var(--mono); font-variant-numeric: tabular-nums; }
.t-unit { color: var(--faint); font-size: 11px; }
.t-delta { margin-left: auto; font: 11px var(--mono); font-variant-numeric: tabular-nums; color: var(--muted); }
.t-delta.bad  { color: var(--crit); }
.t-delta.good { color: var(--ok); }

.t-spark { width: 100%; height: 26px; display: block; margin-top: 2px; }
.sp-line { fill: none; stroke: #4a5570; stroke-width: 1.4px; vector-effect: non-scaling-stroke; }
.st-warn .sp-line { stroke: var(--warn); }
.st-crit .sp-line { stroke: var(--crit); }
.sp-area { fill: rgba(148, 163, 198, .08); stroke: none; }
.th { stroke-width: 1px; stroke-dasharray: 3 3; vector-effect: non-scaling-stroke; display: none; }
.th-warn { stroke: var(--warn); }
.th-crit { stroke: var(--crit); }
.th.show { display: inline; }

/* ---------- 右栏：inspector + feed ---------- */
#side {
  border-left: 1px solid var(--line);
  background: var(--panel);
  display: flex;
  flex-direction: column;
  min-height: 0;
}

#inspector { flex: 1 1 auto; overflow-y: auto; padding: 12px 14px; min-height: 0; }
.insp-empty { color: var(--faint); text-align: center; padding: 48px 18px; }
.empty-title { font-size: 14px; color: var(--muted); margin: 0 0 8px; }
.empty-hint { font-size: 11px; margin-top: 18px; }

.insp-head { display: flex; align-items: center; gap: 8px; }
.insp-head h2 { font-size: 15px; margin: 0; }
.insp-meta { color: var(--muted); font-size: 11.5px; margin: 4px 0 0; }
.insp-meta .dot { margin: 0 4px; color: var(--faint); }
.insp-since { font: 11.5px var(--mono); color: var(--warn); margin: 3px 0 10px; font-variant-numeric: tabular-nums; }
.insp-since.ok { color: var(--ok); }

#insp-chart { width: 100%; height: 150px; display: block; background: var(--panel-2); border: 1px solid var(--line); border-radius: 6px; }
.ch-line { fill: none; stroke: #6d7ba0; stroke-width: 1.6px; vector-effect: non-scaling-stroke; }
.ch-hot { fill: none; stroke: var(--crit); stroke-width: 2px; vector-effect: non-scaling-stroke; }
.ch-hot.warn-hot { stroke: var(--warn); }
.ch-area { fill: rgba(120, 136, 180, .10); stroke: none; }
.ch-legend { display: flex; gap: 12px; color: var(--faint); font-size: 10.5px; margin: 5px 0 12px; }
.lg-warn { color: var(--warn); } .lg-crit { color: var(--crit); } .lg-hot { color: var(--muted); }

#inspector h3 { font-size: 12px; color: var(--muted); margin: 14px 0 6px; font-weight: 600; }
.h3-sub { color: var(--faint); font-weight: 400; font-size: 10.5px; margin-left: 5px; }

#insp-points { list-style: none; margin: 0; padding: 0; font: 11.5px var(--mono); font-variant-numeric: tabular-nums; }
#insp-points li {
  display: grid;
  grid-template-columns: 66px 1fr 84px 44px;
  gap: 6px;
  padding: 3px 6px;
  border-radius: 4px;
  color: var(--muted);
}
#insp-points li:nth-child(odd) { background: rgba(255,255,255,.025); }
#insp-points li.is-crit { color: var(--crit); }
#insp-points li.is-warn { color: var(--warn); }
.p-delta { text-align: right; color: var(--faint); }
.p-st { text-align: right; font-size: 10px; }

/* ---------- 异常事件流 ---------- */
#feed-sec {
  flex: 0 0 auto;
  max-height: 42%;
  overflow-y: auto;
  border-top: 1px solid var(--line);
  padding: 10px 14px 12px;
}
.feed-title { font-size: 12px; color: var(--muted); margin: 0 0 7px; font-weight: 600; }
#feed { list-style: none; margin: 0; padding: 0; }
#feed li {
  display: flex;
  align-items: baseline;
  gap: 7px;
  padding: 4px 2px;
  border-bottom: 1px dashed rgba(255,255,255,.05);
  font-size: 12px;
  color: var(--muted);
}
#feed time { font: 10.5px var(--mono); color: var(--faint); flex: 0 0 auto; font-variant-numeric: tabular-nums; }
#feed .fe-chip { flex: 0 0 auto; font: 700 9.5px var(--mono); border-radius: 3px; padding: 1px 4px; letter-spacing: .5px; }
#feed .fe-chip.crit { color: #fff; background: var(--crit); }
#feed .fe-chip.warn { color: #1a1200; background: var(--warn); }
#feed .fe-chip.ok { color: var(--ok); background: rgba(63,185,111,.12); }
.fe-name {
  background: none; border: none; padding: 0;
  color: var(--text); font: inherit; cursor: pointer;
  text-decoration: underline dotted var(--faint);
  text-underline-offset: 2px;
}
.fe-name:hover { color: var(--accent); }
.fe-desc { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
#feed .fe-empty { color: var(--faint); border: none; }

/* 动效尊重系统偏好：心跳之外本应用无任何动画 */
@media (prefers-reduced-motion: reduce) {
  .hb-dot { animation: none; }
  .tile { transition: none; }
}

